{"command":"python3 -c "
import csv
import math

# Read both files
poi_data = []
with open('outputs/t09_poi_nearest_stop.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        poi_data.append({
            'qid': row['qid'],
            'label': row['label'],
            'poi_type': row['poi_type'],
            'nearest_stop_id': row['nearest_stop_id'],
            'distance_m': float(row['distance_m'])
        })

stop_data = {}
with open('outputs/t06_stop_service_intensity.csv', 'r', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        stop_id = row['stop_id']
        stop_data[stop_id] = {
            'n_departures': int(row['n_departures']),
            'n_routes': int(row['n_routes'])
        }

# Check for missing stops
missing = []
for poi in poi_data:
    if poi['nearest_stop_id'] not in stop_data:
        missing.append(poi['qid'])

if missing:
    print('Missing stops:')
    for m in missing:
        print(f'  {m}')
else:
    print('All stops found!')
""}

